$cookies=[]; $csrf=''; $checks=0;
function checkCms(bool $ok,string $message):void { global $checks; if(!$ok)throw new RuntimeException($message);$checks++; }
function cmsRequest(string $action,?array $data=null,array $extra=[],?string $body=null,?string $type=null):array {
    global $cookies,$csrf;
    $headers=['Origin'=>'http://127.0.0.1:8082','Cookie'=>implode('; ',array_map(fn($k,$v)=>"$k=$v",array_keys($cookies),$cookies))];
    $post=$data!==null||$body!==null;
    if($post)$headers+=['Content-Type'=>$type??'application/json','X-CSRF-Token'=>$csrf];
    $headers=array_replace($headers,$extra);
    $response=file_get_contents('http://127.0.0.1:8082/api/index.php?action='.$action,false,stream_context_create(['http'=>['method'=>$post?'POST':'GET','ignore_errors'=>true,'timeout'=>20,'header'=>implode("\r\n",array_map(fn($k,$v)=>"$k: $v",array_keys($headers),$headers)),'content'=>$body??($data!==null?json_encode($data):'')]]));
    $status=(int)explode(' ',$http_response_header[0])[1];
    foreach($http_response_header as $header)if(preg_match('/^Set-Cookie: ([^=]+)=([^;]*)/i',$header,$match))$cookies[$match[1]]=$match[2];
    return [$status,json_decode($response,true),$response,$http_response_header];
}
